@Test
public void testValidatingParameter() {
    // Testing with default (validation ON).
    try {
        URL configFile = this.getClass().getClassLoader().getResource("org/apache/tiles/config/invalid-defs.xml");
        assertNotNull("Config file not found", configFile);
        InputStream source = configFile.openStream();
        reader.setValidating(true);
        reader.read(source);
        fail("Should've thrown an exception.");
    } catch (DefinitionsFactoryException e) {
        assertTrue(true);
    } catch (Exception e) {
        fail("Exception reading configuration." + e);
    }
    // Testing with validation OFF.
    try {
        setUp();
        URL configFile = this.getClass().getClassLoader().getResource("org/apache/tiles/config/invalid-defs.xml");
        assertNotNull("Config file not found", configFile);
        InputStream source = configFile.openStream();
        reader.read(source);
    } catch (DefinitionsFactoryException e) {
        fail("Should not have thrown an exception." + e);
    } catch (Exception e) {
        fail("Exception reading configuration." + e);
    }
}

